<?php
if(!defined('ABSPATH'))exit;
class SMF_Attribution_Intelligence{
 public static function init(){add_action('admin_menu',array(__CLASS__,'menu'),30);add_action('admin_init',array(__CLASS__,'settings'));add_action('admin_post_smf_attr_int_export',array(__CLASS__,'export'));}
 public static function settings(){register_setting('smf_settings','smf_attribution_model',array('sanitize_callback'=>function($v){return SMF_Attribution_Model::normalize_model($v);}));}
 public static function menu(){add_submenu_page('sync-meta-flow','Attribution Intelligence','Attribution Intelligence','manage_woocommerce','smf-attribution-intelligence',array(__CLASS__,'render'));}
 private static function touch($m,$p){$o=array();foreach(array('campaign_id','adset_id','ad_id','utm_campaign','campaign_name') as $k){$x=$p?$p.'_'.$k:$k;if(!empty($m[$x]))$o[$k]=sanitize_text_field((string)$m[$x]);}return $o;}
 private static function name($t){foreach(array('campaign_name','utm_campaign','campaign_id') as $k)if(!empty($t[$k]))return sanitize_text_field($t[$k]);return 'Direct / Unattributed';}
 private static function data($since,$until,$currency,$model){global $wpdb;$e=$wpdb->prefix.'smf_order_events';$s=$wpdb->prefix.'smf_campaign_spend';$ids=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT order_id FROM $e WHERE event_type='purchase' AND created_at BETWEEN %s AND %s",$since.' 00:00:00',$until.' 23:59:59'));$orders=array();if($ids){$in=implode(',',array_map('absint',$ids));$rows=$wpdb->get_results("SELECT order_id,event_type,new_status,metadata FROM $e WHERE order_id IN ($in) ORDER BY order_id ASC,id ASC");foreach($rows as $r){$id=(int)$r->order_id;$orders[$id]??=array('v'=>0,'cur'=>'','purchase'=>false,'confirmed'=>false,'shipped'=>false,'delivered'=>false,'cancelled'=>false,'returned'=>false,'first'=>array(),'last'=>array());$m=$r->metadata?json_decode($r->metadata,true):array();if(isset($m['order_total']))$orders[$id]['v']=(float)$m['order_total'];if(!empty($m['currency']))$orders[$id]['cur']=sanitize_text_field($m['currency']);if($r->event_type==='purchase'){$orders[$id]['purchase']=true;$orders[$id]['first']=self::touch($m,'first');$orders[$id]['last']=self::touch($m,'last');if(!$orders[$id]['last'])$orders[$id]['last']=self::touch($m,'');}$st=(string)$r->new_status;if(in_array($st,array('smf-confirmed','processing','on-hold','completed','smf-shipped','smf-delivered'),true))$orders[$id]['confirmed']=true;if(in_array($st,array('smf-shipped','smf-delivered','completed'),true))$orders[$id]['shipped']=true;if(in_array($st,array('smf-delivered','completed'),true))$orders[$id]['delivered']=true;if($st==='cancelled')$orders[$id]['cancelled']=true;if(in_array($st,array('smf-returned','refunded'),true))$orders[$id]['returned']=true;}}
 $sp=$wpdb->get_results($wpdb->prepare("SELECT campaign_id,amount,currency FROM $s WHERE spend_date BETWEEN %s AND %s AND currency=%s",$since,$until,$currency));$spend=0;$cs=array();foreach($sp as $r){$a=(float)$r->amount;$spend+=$a;if($r->campaign_id!=='')$cs[$r->campaign_id]=($cs[$r->campaign_id]??0)+$a;}
 $rows=array();$summary=array('spend'=>$spend,'orders'=>0,'purchase_revenue'=>0,'delivered_orders'=>0,'delivered_revenue'=>0,'confirmed_orders'=>0,'shipped_orders'=>0,'cancelled_orders'=>0,'returned_orders'=>0,'assisted_orders'=>0,'assisted_revenue'=>0,'model_credit_revenue'=>0);$ads=array();
 foreach($orders as $o){if(!$o['purchase']||strtoupper($o['cur'])!==strtoupper($currency))continue;$v=$o['v'];$summary['orders']++;$summary['purchase_revenue']+=$v;if($o['confirmed'])$summary['confirmed_orders']++;if($o['shipped'])$summary['shipped_orders']++;if($o['delivered']){$summary['delivered_orders']++;$summary['delivered_revenue']+=$v;}if($o['cancelled'])$summary['cancelled_orders']++;if($o['returned'])$summary['returned_orders']++;$f=self::name($o['first']);$l=self::name($o['last']);if($f!==$l){$summary['assisted_orders']++;if($o['delivered'])$summary['assisted_revenue']+=$v;}$credits=array();if($model==='first_touch')$credits=array($f=>$v);elseif($model==='last_touch')$credits=array($l=>$v);elseif($model==='assisted'){$credits=($f!==$l&&$f!=='Direct / Unattributed')?array($f=>$v):array();}elseif($f!==$l)$credits=array($f=>$v/2,$l=>$v/2);else $credits=array($f=>$v);foreach($credits as $c=>$credit){if(!isset($rows[$c]))$rows[$c]=array('campaign'=>$c,'credit_revenue'=>0,'orders'=>0,'delivered_orders'=>0,'spend'=>0);$rows[$c]['credit_revenue']+=$o['delivered']?$credit:0;$rows[$c]['orders']++;if($o['delivered']){$rows[$c]['delivered_orders']++;$summary['model_credit_revenue']+=$credit;}}
 $ad_credits=array();if($model==='first_touch')$ad_credits=array($o['first']);elseif($model==='last_touch')$ad_credits=array($o['last']);elseif($model==='first_last'&&$f!==$l)$ad_credits=array(array('t'=>$o['first'],'w'=>0.5),array('t'=>$o['last'],'w'=>0.5));elseif($model==='assisted')$ad_credits=($f!==$l&&$f!=='Direct / Unattributed')?array($o['first']):array();else $ad_credits=array($o['last']);foreach($ad_credits as $entry){$t=isset($entry['t'])?$entry['t']:$entry;$w=isset($entry['w'])?(float)$entry['w']:1;if(empty($t['ad_id']))continue;$a=sanitize_text_field($t['ad_id']);$ads[$a]??=array('ad_id'=>$a,'campaign'=>self::name($t),'delivered_revenue'=>0,'orders'=>0);if($o['delivered']){$ads[$a]['delivered_revenue']+=$v*$w;$ads[$a]['orders']++;}}
 }
 foreach($rows as &$r){$r['spend']=$cs[$r['campaign']]??0;$r['roas']=$r['spend']>0?$r['credit_revenue']/$r['spend']:0;$r['decision']=$r['spend']<=0?'NO SPEND':($r['roas']>=3?'SCALE':($r['roas']>=1?'WATCH':'KILL'));}unset($r);usort($rows,function($a,$b){return $b['roas']<=>$a['roas'];});$track=$wpdb->get_results($wpdb->prepare("SELECT event_name,COUNT(*) events,COUNT(DISTINCT session_key) sessions FROM {$wpdb->prefix}smf_tracking_events WHERE created_at BETWEEN %s AND %s GROUP BY event_name",$since.' 00:00:00',$until.' 23:59:59'),ARRAY_A);$funnel=array();foreach($track as $r)$funnel[$r['event_name']]=array('events'=>(int)$r['events'],'sessions'=>(int)$r['sessions']);$summary['roas']=$spend>0?$summary['model_credit_revenue']/$spend:0;return array('summary'=>$summary,'campaigns'=>$rows,'ads'=>array_values($ads),'funnel'=>$funnel);}
 private static function range(){ $d=isset($_GET['period'])&&in_array(absint($_GET['period']),array(7,30,90),true)?absint($_GET['period']):30;$u=current_time('Y-m-d');$s=wp_date('Y-m-d',strtotime('-'.($d-1).' days',current_time('timestamp')));return array($d,$s,$u);}
 public static function export(){if(!current_user_can('manage_woocommerce'))wp_die('Permission denied.',403);check_admin_referer('smf_attr_int_export');$m=SMF_Attribution_Model::normalize_model(isset($_GET['model'])?wp_unslash($_GET['model']):get_option('smf_attribution_model','last_touch'));$cur=isset($_GET['currency'])?strtoupper(sanitize_text_field(wp_unslash($_GET['currency']))):'BDT';list($d,$s,$u)=self::range();$x=self::data($s,$u,$cur,$m);$fmt=isset($_GET['format'])?sanitize_key($_GET['format']):'csv';if($fmt==='json'){nocache_headers();header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename=smf-attribution.json');echo wp_json_encode(array('period'=>array('days'=>$d,'since'=>$s,'until'=>$u),'currency'=>$cur,'model'=>$m,'data'=>$x));exit;}nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=smf-attribution.csv');$o=fopen('php://output','w');fputcsv($o,array('Campaign','Spend','Credit Revenue','Orders','Delivered Orders','ROAS','Decision'));foreach($x['campaigns'] as $r)fputcsv($o,array($r['campaign'],$r['spend'],$r['credit_revenue'],$r['orders'],$r['delivered_orders'],round($r['roas'],4),$r['decision']));fclose($o);exit;}
 public static function render(){if(!current_user_can('manage_woocommerce'))return;$m=SMF_Attribution_Model::normalize_model(isset($_GET['model'])?wp_unslash($_GET['model']):get_option('smf_attribution_model','last_touch'));$cur=isset($_GET['currency'])?strtoupper(sanitize_text_field(wp_unslash($_GET['currency']))):'BDT';list($d,$s,$u)=self::range();$x=self::data($s,$u,$cur,$m);$z=$x['summary'];$nonce=wp_create_nonce('smf_attr_int_export');$url=admin_url('admin-post.php?action=smf_attr_int_export&period='.$d.'&currency='.rawurlencode($cur).'&model='.rawurlencode($m).'&_wpnonce='.$nonce);?><div class="wrap smf-wrap"><div class="smf-header"><div><h1>Attribution Intelligence</h1><p>Single-source financial spend, cohort-correct delivery outcomes and explicit attribution credit.</p></div></div><form method="get" class="smf-period-bar"><input type="hidden" name="page" value="smf-attribution-intelligence"><label>Model <select name="model"><option value="last_touch" <?php selected($m,'last_touch');?>>Last Touch</option><option value="first_touch" <?php selected($m,'first_touch');?>>First Touch</option><option value="first_last" <?php selected($m,'first_last');?>>First + Last (50/50)</option><option value="assisted" <?php selected($m,'assisted');?>>Assisted First-Touch Influence</option></select></label><?php foreach(array(7,30,90) as $p):?><a class="button <?php echo $d===$p?'button-primary':'';?>" href="<?php echo esc_url(admin_url('admin.php?page=smf-attribution-intelligence&period='.$p.'&currency='.rawurlencode($cur).'&model='.rawurlencode($m)));?>"><?php echo esc_html($p);?> days</a><?php endforeach;?><button class="button">Apply</button></form><form method="post" action="<?php echo esc_url(admin_url('options.php'));?>" style="margin:10px 0"><?php settings_fields('smf_settings');?><input type="hidden" name="smf_attribution_model" value="<?php echo esc_attr($m);?>"><button class="button">Save selected model</button></form><p><a class="button" href="<?php echo esc_url($url.'&format=csv');?>">Export CSV</a> <a class="button" href="<?php echo esc_url($url.'&format=json');?>">Export JSON</a></p><div class="smf-cards"><div class="smf-card"><span>Spend</span><strong><?php echo esc_html(number_format_i18n($z['spend'],2));?></strong><small>Each spend row counted once</small></div><div class="smf-card"><span>Delivered Revenue</span><strong><?php echo esc_html(number_format_i18n($z['delivered_revenue'],2));?></strong><small><?php echo esc_html($z['delivered_orders']);?> delivered</small></div><div class="smf-card"><span>Selected ROAS</span><strong><?php echo esc_html(number_format_i18n($z['roas'],2));?>×</strong><small><?php echo esc_html(SMF_Attribution_Model::label($m));?></small></div><div class="smf-card"><span>Assisted Journeys</span><strong><?php echo esc_html($z['assisted_orders']);?></strong><small><?php echo esc_html(number_format_i18n($z['assisted_revenue'],2));?> delivered revenue</small></div></div><div class="smf-panel"><h2>Funnel</h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Stage</th><th>Events</th><th>Unique Sessions</th></tr></thead><tbody><?php foreach(array('page_view'=>'PageView','view_content'=>'ViewContent','add_to_cart'=>'Add to Cart','initiate_checkout'=>'Initiate Checkout','purchase'=>'Purchase') as $k=>$label):?><tr><td><?php echo esc_html($label);?></td><td><?php echo esc_html($x['funnel'][$k]['events']??0);?></td><td><?php echo esc_html($x['funnel'][$k]['sessions']??0);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="smf-panel"><h2>Campaign decisions</h2><p class="smf-muted">Campaign credit follows the selected model. Spend is matched only by campaign_id, so campaign/adset/ad namespaces cannot be double-counted. SCALE ≥ 3×, WATCH 1–2.99×, KILL &lt; 1× are operational heuristics, not profit guarantees.</p><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Campaign</th><th>Spend</th><th>Credit Revenue</th><th>Orders</th><th>Delivered</th><th>ROAS</th><th>Decision</th></tr></thead><tbody><?php foreach($x['campaigns'] as $r):?><tr><td><strong><?php echo esc_html($r['campaign']);?></strong></td><td><?php echo esc_html(number_format_i18n($r['spend'],2));?></td><td><?php echo esc_html(number_format_i18n($r['credit_revenue'],2));?></td><td><?php echo esc_html($r['orders']);?></td><td><?php echo esc_html($r['delivered_orders']);?></td><td><?php echo esc_html(number_format_i18n($r['roas'],2));?>×</td><td><?php echo esc_html($r['decision']);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="smf-panel"><h2>Ad-level attribution</h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Ad ID</th><th>Campaign</th><th>Delivered Revenue</th><th>Delivered Orders</th></tr></thead><tbody><?php foreach($x['ads'] as $a):?><tr><td><?php echo esc_html($a['ad_id']);?></td><td><?php echo esc_html($a['campaign']);?></td><td><?php echo esc_html(number_format_i18n($a['delivered_revenue'],2));?></td><td><?php echo esc_html($a['orders']);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="smf-panel"><h2>Model rules</h2><p class="smf-muted">First Touch = acquisition credit. Last Touch = conversion credit. First + Last = 50/50 when endpoints differ. Assisted = first-touch influence only when endpoints differ. These views are alternatives and must never be added together. Only first and last touch are retained; this is not full all-touch multi-touch attribution.</p></div></div><?php }
}
